ee:message.ee:set-payload:
%dw 2.0
output application/json

// Estos serían los parámetros que recibes de tu flujo o petición
var currentTech = lower(vars.RequestOrder.category)
var currentTramite = lower(vars.RequestOrder.through.throughType)
var currentChannel = lower(vars.RequestOrder.channel)

---
payload filter ((regla) -> 
    regla.habilitada == true 
    and 
    // 2. Convertimos la lista de tecnologías a minúsculas antes de comparar
    ((regla.aplicaA.tecnologias map lower($)) contains currentTech)
    and
    // 3. Lo mismo para tipos de trámite
    ((regla.aplicaA.tiposTramite map lower($)) contains currentTramite)
    and
    // 4. Y para el canal
    (if (regla.aplicaA.canal != null) 
        ((regla.aplicaA.canal map lower($)) contains currentChannel)
     else true)
)

%dw 2.0
output application/json
---
{
	code: "500",
	messageResponse: "Error Created Order",
	order: {
		rulesApplied: vars.reglasAcumuladas map (regla) -> {
			idRule: regla.idRegla,
	        isValid: regla.esValido,
	        mandatory: regla.obligatoria,
	        detailedEvaluation: regla.evaluacionDetallada map (detalle) -> {
	            compared: detalle.comparacion,
	            description: detalle.descripcion,
	            mandatory: detalle.obligatoria,
	            result: detalle.resultado
	        },

	        responseRule: {
	            code: regla.respuestaRegla.codigo,
	            message: regla.respuestaRegla.mensaje
	        }
	    }
	}

}

