%dw 2.0
output application/json
---
{
	basePath: p("mongo-db-sapi.base-path"),
	host: p("mongo-db-sapi.host"),
	port: p("mongo-db-sapi.port"),
	method: "POST",
	path: "/dynamicQuery",
	body: { 
		"query" :{
  "aggregate": "CMP_OFERTA_PRODUCTO",
  "pipeline": [
    {
      "\$match": {
        // Aquí usamos el valor dinámico que viene de tu flujo de Mule
        "num_agrupacion": vars.RequestOrder.requestService.productGroupingNumber default 0
      }
    },
    {
      "\$group": {
        "_id": "\$num_agrupacion",
        "bundle": {
          "\$push": {
            "\$cond": [
              { "\$eq": ["\$tipo_producto", "BUNDLE"] },
              "\$\$ROOT",
              "\$\$REMOVE"
            ]
          }
        },
        "primarios": {
          "\$push": {
            "\$cond": [
              { "\$eq": ["\$tipo_producto", "Primario"] },
              "\$\$ROOT",
              "\$\$REMOVE"
            ]
          }
        },
        "secundarios": {
          "\$push": {
            "\$cond": [
              { "\$in": ["\$tipo_producto", ["SECUNDARIO"]] },
              "\$\$ROOT",
              "\$\$REMOVE"
            ]
          }
        }
      }
    },
    {
      "\$addFields": {
        "bundle": { "\$arrayElemAt": ["\$bundle", 0] }
      }
    },
    {
      "\$addFields": {
        "primarios": {
          "\$map": {
            "input": "\$primarios",
            "as": "prim",
            "in": {
              "\$mergeObjects": [
                "\$\$prim",
                {
                  "secundarios": {
                    "\$filter": {
                      "input": "\$secundarios",
                      "as": "sec",
                      "cond": {
                        "\$eq": [
                          "\$\$sec.id_producto_principal",
                          { "\$toString": "\$\$prim._id" }
                        ]
                      }
                    }
                  }
                }
              ]
            }
          }
        }
      }
    },
    {
      "\$addFields": {
        "primarios": {
          "\$sortArray": {
            "input": "\$primarios",
            "sortBy": { "secuencia": 1 }
          }
        }
      }
    },
    {
      "\$addFields": {
        "bundle": {
          "\$mergeObjects": [
            "\$bundle",
            { "primarios": "\$primarios" }
          ]
        }
      }
    },
    {
      "\$project": {
        "_id": 0,
        "num_agrupacion": "\$_id",
        "bundle": 1
      }
    }
  ],
  "cursor": {}
}
	},
	headers: {
	"client_secret" : p('mongo-db-sapi.security.client-secret'),
	"client_id" : p('mongo-db-sapi.security.client-id'),
	"name": vars.headers.name,
	"X-CORRELATION-ID": vars.headers."X-CORRELATION-ID",
	"source": vars.headers.source,
	"systemId": vars.headers.systemId
},
	queryParameters:{

	},
	uriParameters:{

	}
}

