%dw 2.0
output application/json

// 1. Accedemos a los datos de entrada
var inputData = vars.RequestOrder default {}
var orderNum = (vars.resultadoConsecutivo.result.value.Prefijo default "") ++ (vars.resultadoConsecutivo.result.value.Secuencia as String default "")

// 2. LA CLAVE: Función para buscar el objeto dentro del array de la variable
// Busca en el array donde 'llave' coincida con el nombre y devuelve el campo 'objeto'
fun findObject(nombreLlave) = 
    (vars.resultadoSapi filter ($.llave == nombreLlave))[0].objeto default {}

// Función para formatear fechas al estilo MongoDB
fun toDate(d) = if (isEmpty(d)) null else { "\$date": d }

// --- FUNCIÓN PARA EL CALCULO DEL ESTADO---
fun calcularEstadoComercial(reglas) = do {
    // 1. Limpiamos y ordenamos por código para asegurar la línea de tiempo
    var estadosLimpios = (reglas map (item) -> {
        "esValido": item.esValido default false,
        "estadoOrdenComercial": item.estadoOrdenComercial
    }) orderBy (item) -> item.estadoOrdenComercial.codigo

    // 2. Filtramos solo las reglas que SI SE CUMPLIERON
    var reglasExitosas = estadosLimpios filter (item) -> item.esValido == true

    // 3. ¿Falló algo opcional? 
    // Comparamos si el número de éxitos es igual al total de reglas enviadas
    var todasPasaron = sizeOf(reglasExitosas) == sizeOf(estadosLimpios)

    // Definimos la fecha actual una sola vez para que sea consistente
    var fechaActual = { "\$date": now() as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSS'Z'"} }

    ---
    if (todasPasaron)
        // CASO 1: Éxito total -> Estado Maestro
        {
            "Codigo": p("status-orchestrator.code"),
            "Descripcion": p("status-orchestrator.description"),
            "Fecha": fechaActual,
            "Reintentos": 0,
            "CodigoExcepcion": 0
        }
    else
        // CASO 2: Algo falló (pero no fue obligatorio) 
        // Retornamos el estado de la ÚLTIMA regla que sí tuvo éxito
        (reglasExitosas[-1].estadoOrdenComercial ++ { 
        "Fecha": fechaActual default "" ,
            "Reintentos": 0,
            "CodigoExcepcion": 0
        } default {})
}

---
{
	basePath: p("mongo-db-sapi.base-path"),
	host: p("mongo-db-sapi.host"),
	port: p("mongo-db-sapi.port"),
	method: "POST",
	path: "/dynamicQuery",
	body: { 
  "query" : {
    "insert": "MDM_CD_ORDEN",
    "documents": [
      {
        "Fecha_Creacion": toDate(inputData.createdAt),
        "Fecha_Modificacion": toDate(inputData.updatedAt),
        "Usuario_Modificacion": inputData.updatedBy,
        "Usuario_Creacion": inputData.createdBy,
        "Actualizacion_Extractor": inputData.extractorUpdate,
        "Numero_Orden": orderNum,
        "Canal": inputData.channel,
        "Fase": inputData.phase,

        "Estado_Orden_Comercial": calcularEstadoComercial(vars.reglasAcumuladas),

        "Tramite": {
          "Tipo_Tramite": inputData.through.throughType,
          "Subtipo_Tramite": if (isEmpty(inputData.through.throughSubtype)) null else inputData.through.throughSubtype,
          "Fecha_Tramite": toDate(inputData.through.throughDate),
          "Fecha_Reconexion": toDate(inputData.through.reconnectionDate),
          "Fecha_Suspension": toDate(inputData.through.suspensionDate),
          "Fecha_Ejecucion": toDate(inputData.through.executionDate),
          "Conservar_Numero_Conexion": inputData.through.keepConnectionNumber,
          "Clausula_Permanencia": inputData.through.permanenceClause,
          "Valor_Clausula_Permanencia": inputData.through.permanenceClauseValue,
          "Causal_Cancelacion": if (isEmpty(inputData.through.cancellationReason)) null else inputData.through.cancellationReason,
          "Subcausal_Cancelacion": if (isEmpty(inputData.through.cancellationSubreason)) null else inputData.through.cancellationSubreason,
          "Descripcion_Cancelacion": if (isEmpty(inputData.through.cancellationDescription)) null else inputData.through.cancellationDescription,
          "MotivosOrden": if (isEmpty(inputData.through.orderMotives)) null else inputData.through.orderMotives
        },

        "CUN": inputData.cun,

        // --- AQUÍ USAMOS LA FUNCIÓN ---
        "Cliente_Tramite": findObject("MDM_CLIENTE"),

        "Servicio_Tramite": vars.resultadoProductos.Servicio_Tramite,
        "Orden_Servicio": {},
        "Agendamiento":{},
        "Orden_Activacion": null,
  		"Cuenta_Facturacion_Anterior": null,
  		"Cuenta_Facturacion_Tramite":{},
  		"Orden_Requiere_Disponibilidad": null,
	  	"Orden_Requiere_Agendamiento": null,
	  	"Precio_Total_Orden": "",
	  	"Adjuntos": {
        "Servicio": (inputData.attachments.service default []) map (item) -> {
            "nombre": item.fileName,
            "ruta": item.path,
            "tamano": item.size
        }
    },
	  	"Adjuntos_Cliente": null,
  		"Adjuntos_Servicio": null,
  		"Caracteristica_Orden": inputData.orderCharacteristics default [] map (item) -> {
	        "Caracteristica": item.characteristic,
	        "Valor": item.value
    	},
  		"Otros": {
		    "Envio_Contrato": "",
		    "Usuario_Venta": "",
		    "Medio_Comunicacion": ""
		  },
		 "Presencial": false,
  		 "OfertaSugerida": [],
  	 	 "Reserva": null
      }
    ]
  }
},
	headers: {
	"client_secret" : p('mongo-db-sapi.security.client-secret'),
	"client_id" : p('mongo-db-sapi.security.client-id'),
	"name": vars.headers.name,
