---
{
	code: if(payload."0".payload.result.ok > 0) "200" else "500",
	messageResponse: if(payload."0".payload.result.ok > 0) "Order Created" else "Error Created Order",
	order: {
		orderNUmber: vars.orderNumber default "",

		rulesApplied: vars.reglasAcumuladas map (regla) -> {
			idRule: regla.idRegla,
	        isValid: regla.esValido,
	        mandatory: regla.obligatoria,
	        detailedEvaluation: regla.evaluacionDetallada map (detalle) -> {
	            compared: detalle.comparacion,
	            description: detalle.descripcion,
	            mandatory: detalle.obligatoria,
	            result: detalle.resultado
	        },

