#[%dw 2.0
output application/json

// IDs que la regla actual exige
var idsRequeridos = vars.currentRule.dependencias.reglas default []

// El histórico, si es la primera vez, será un array vacío
var historico = vars.reglasAcumuladas default []

// Buscamos en el histórico
var dependenciasEncontradas = historico filter ((acumulada) -> 
    idsRequeridos contains acumulada.idRegla
)

// PASO DE SEGURIDAD 1: ¿Están todas? 
// (Si es la primera ejecución y hay requeridas, esto dará FALSE automáticamente)
var estanTodas = if (isEmpty(idsRequeridos)) true 
                 else sizeOf(dependenciasEncontradas) == sizeOf(idsRequeridos)

// PASO DE SEGURIDAD 2: ¿Son válidas?
var todasSonValidas = sizeOf(dependenciasEncontradas filter ($.esValido == false)) == 0

---
// Lógica para el Choice:
// Si la regla dice que es dependiente, pero el historial no tiene lo que ella necesita... 
// devuelve TRUE (bloquea y manda al camino de error).
(vars.currentRule.dependencias.esDependiente default false) and (!(estanTodas and todasSonValidas))]

ee:variables.ee:set-variable:
%dw 2.0
output application/json
---
do {
    // 1. Tomamos lo que ya tiene la variable o inicializamos con vacío
    var acumulado = vars.reglasAcumuladas default []

    // 2. Creamos el objeto de la regla actual
    var resultadoActual = {
		idRegla: vars.currentRule.idRegla default "",
		obligatoria: vars.currentRule.obligatoria default false,
		evaluacionDetallada: [{
			descripcion: "No ejecutada: Una o más dependencias fallaron o no existen.",
			comparacion: "N/A",
			resultado: "FALLO",
			critica: "",
			obligatoria: ""

		}],
		esValido: false,
		respuestaRegla: vars.currentRule.siFalla default "Rechazo por dependencia",
		estadoOrdenComercial: vars.currentRule.estadoOrdenComercial
	}
    ---
    // 3. Retornamos la lista con el nuevo elemento al final
    acumulado ++ [resultadoActual]
}

ee:message.ee:set-payload:
%dw 2.0
output application/json

// 1. Obtenemos el Request Original
var requestOriginal = vars.RequestOrder 

// 2. Función de navegación segura
fun resolvePath(obj: Any, path: String) = 
    if (path != null) 
        path splitBy "." reduce (key, acc = obj) -> acc[key]
    else null

// 3. Construimos el filtro dinámico basado en las reglas
var dynamicMatch = payload.accion.evaluacionRequest reduce (item, acc = {}) -> (
    if (item.parametro != null and item.valor != null)
        do {


             // Resolvemos el valor real del request usando el path elegido
           var valorReal =
    if ((item.parametro default "") == "==" or isEmpty(item.parametro default ""))
        item.comparacion
    else
        resolvePath(requestOriginal, item.parametro)
            // Construimos la llave final (root o dot notation)
            var llaveFinal = if (item.contenedor == "root") item.valor 
                             else (item.contenedor ++ "." ++ item.valor)
// --- LÓGICA DE TRANSFORMACIÓN DE VALOR ---
            var valorFinal = if (item.valor == "_id") 
                                { "\$oid": valorReal } // Si es _id, aplicamos formato ObjectId
                             else if (item.usaRegex == true) 
                                { "\$regex": valorReal } 
                             else 
                                valorReal
            ---
            acc ++ { (llaveFinal): valorFinal }
        }
    else acc
)

---
if(upper(payload.accion.metodo) == "POST"){
	"query": {
    "aggregate": payload.accion.coleccion,
    "pipeline": [
      {
        // Envolvemos el resultado en un $match para que Mongo filtre
        "\$match": dynamicMatch
      }
    ],
    "cursor": {}
  }
}
else if(upper(payload.accion.metodo) == "GET")
  	dynamicMatch
else
{}

